svg.script:
(function(){
  var ds=["Jul 25, 2026","Jul 26, 2026","Jul 26, 2026 to Jul 27, 2026","Jul 26, 2026 to Jul 28, 2026","Jul 26, 2026 to Jul 29, 2026","Jul 26, 2026 to Jul 30, 2026","Jul 26, 2026 to Jul 31, 2026","Jul 26, 2026 to Aug 1, 2026","Jul 26, 2026 to Aug 2, 2026","Jul 26, 2026 to Aug 3, 2026","Jul 26, 2026 to Aug 4, 2026","Jul 26, 2026 to Aug 5, 2026","Jul 26, 2026 to Aug 6, 2026","Jul 26, 2026 to Aug 7, 2026","Jul 26, 2026 to Aug 10, 2026","Jul 26, 2026 to Aug 11, 2026","Jul 26, 2026 to Aug 12, 2026","Jul 26, 2026 to Aug 13, 2026","Jul 26, 2026 to Aug 14, 2026","Jul 26, 2026 to Aug 15, 2026","Jul 26, 2026 to Aug 16, 2026","Jul 26, 2026 to Aug 17, 2026","Jul 26, 2026 to Aug 18, 2026","Jul 26, 2026 to Aug 19, 2026","Jul 26, 2026 to Aug 20, 2026","Jul 26, 2026 to Aug 21, 2026","Jul 26, 2026 to Aug 22, 2026","Jul 26, 2026 to Aug 23, 2026","Jul 26, 2026 to Aug 24, 2026","Jul 26, 2026 to Aug 25, 2026","Jul 26, 2026 to Aug 26, 2026","Jul 26, 2026 to Aug 27, 2026","Jul 26, 2026 to Aug 28, 2026","Jul 26, 2026 to Aug 29, 2026","Jul 26, 2026 to Aug 30, 2026","Jul 26, 2026 to Aug 31, 2026","Jul 26, 2026 to Sep 1, 2026","Jul 26, 2026 to Sep 2, 2026","Jul 26, 2026 to Sep 3, 2026","Jul 26, 2026 to Sep 4, 2026","Jul 26, 2026 to Sep 5, 2026","Jul 26, 2026 to Sep 6, 2026","Jul 26, 2026 to Sep 7, 2026","Jul 26, 2026 to Sep 8, 2026","Jul 26, 2026 to Sep 9, 2026","Jul 26, 2026 to Sep 10, 2026","Jul 26, 2026 to Sep 11, 2026","Jul 26, 2026 to Sep 12, 2026","Jul 26, 2026 to Sep 13, 2026","Jul 26, 2026 to Sep 14, 2026","Jul 26, 2026 to Sep 15, 2026","Jul 26, 2026 to Sep 16, 2026","Jul 26, 2026 to Sep 17, 2026","Jul 26, 2026 to Sep 20, 2026","Jul 26, 2026 to Sep 21, 2026","Jul 26, 2026 to Sep 22, 2026","Jul 26, 2026 to Sep 23, 2026","Jul 26, 2026 to Sep 24, 2026","Jul 26, 2026 to Sep 25, 2026","Jul 26, 2026 to Sep 26, 2026","Jul 26, 2026 to Sep 27, 2026"];
  var cs=["0 sessions","28 sessions","69 sessions","111 sessions","166 sessions","212 sessions","246 sessions","298 sessions","341 sessions","364 sessions","396 sessions","406 sessions","417 sessions","427 sessions","446 sessions","485 sessions","486 sessions","491 sessions","501 sessions","536 sessions","567 sessions","618 sessions","659 sessions","661 sessions","677 sessions","713 sessions","737 sessions","756 sessions","773 sessions","795 sessions","809 sessions","818 sessions","834 sessions","872 sessions","904 sessions","925 sessions","932 sessions","948 sessions","982 sessions","1,021 sessions","1,021 sessions","1,021 sessions","1,021 sessions","1,030 sessions","1,064 sessions","1,080 sessions","1,092 sessions","1,133 sessions","1,168 sessions","1,184 sessions","1,192 sessions","1,203 sessions","1,218 sessions","1,251 sessions","1,258 sessions","1,258 sessions","1,258 sessions","1,258 sessions","1,258 sessions","1,261 sessions","1,288 sessions"];
  var kt=[0,0.01,0.03,0.04,0.06,0.09,0.11,0.12,0.13,0.14,0.16,0.18,0.19,0.2,0.21,0.23,0.26,0.29,0.31,0.33,0.35,0.36,0.38,0.39,0.42,0.45,0.47,0.48,0.51,0.52,0.54,0.55,0.56,0.57,0.58,0.6,0.63,0.64,0.65,0.66,0.68,0.69,0.71,0.74,0.75,0.75,0.76,0.78,0.8,0.81,0.83,0.84,0.84,0.87,0.89,0.91,0.92,0.94,0.96,0.99,1];
  var dur=18;
  var el=document.getElementById("plot-date");
  var ct=document.getElementById("plot-sessions");
  if(!el)return;
  var svg=el.ownerSVGElement;
  function upd(){
    var t=svg.getCurrentTime()/dur;
    if(t<0)t=0;if(t>1)t=1;
    var idx=0;
    for(var i=1;i<kt.length;i++){
      if(t>=kt[i])idx=i;
    }
    el.textContent=ds[idx];ct.textContent=cs[idx];
  }
  svg.addEventListener("ccp-seek",upd);
  setInterval(upd,200);
})();

(function(){
  var box=document.getElementById("plot-scrubber");
  var svg=box.ownerSVGElement;
  var input=document.getElementById("plot-scrub-input");
  var play=document.getElementById("plot-play");
  var kt=[0,0.01,0.03,0.04,0.06,0.09,0.11,0.12,0.13,0.14,0.16,0.18,0.19,0.2,0.21,0.23,0.26,0.29,0.31,0.33,0.35,0.36,0.38,0.39,0.42,0.45,0.47,0.48,0.51,0.52,0.54,0.55,0.56,0.57,0.58,0.6,0.63,0.64,0.65,0.66,0.68,0.69,0.71,0.74,0.75,0.75,0.76,0.78,0.8,0.81,0.83,0.84,0.84,0.87,0.89,0.91,0.92,0.94,0.96,0.99,1];
  var dur=18;
  var paused=false;
  function reveal(){
    box.style.opacity="1";box.style.pointerEvents="auto";
  }
  function seek(i){
    if(!paused){svg.pauseAnimations();paused=true;}
    svg.setCurrentTime(kt[i]*dur);input.value=i;
    svg.dispatchEvent(new Event("ccp-seek"));
  }
  input.addEventListener("input",function(){
    seek(parseInt(input.value,10));
  });
  play.addEventListener("click",function(){
    svg.setCurrentTime(0);svg.unpauseAnimations();paused=false;
    window.setTimeout(function(){
      if(!paused){seek(kt.length-1);}
    },dur*1000+50);
  });
  svg.pauseAnimations();paused=true;seek(kt.length-1);reveal();
})();

(function(){
  var NS="http://www.w3.org/2000/svg";
  var svg=document.documentElement;
  var g=document.getElementById("plot-tooltip");
  var bx=document.getElementById("plot-tooltip-box");
  var tx=document.getElementById("plot-tooltip-text");
  var ic=document.getElementById("plot-tooltip-icons");
  var pad=8.0;
  var lh=16.0;
  var isz=14.0;
  var vw=800;
  var vh=1100;
  function titleOf(n){
    var c=n.childNodes||[];
    for(var i=0;i<c.length;i++){
      if(c[i].nodeName==="title")return c[i].textContent;
    }
    return null;
  }
  function findTooltip(n){
    while(n&&n!==svg){
      if(titleOf(n)!==null)return n;
      n=n.parentNode;
    }
    return null;
  }
  function pt(e){
    var m=svg.getScreenCTM();
    if(!m)return null;
    var p=svg.createSVGPoint();
    p.x=e.clientX;p.y=e.clientY;
    return p.matrixTransform(m.inverse());
  }
  function clear(n){
    while(n.firstChild)n.removeChild(n.firstChild);
  }
  function hide(){g.setAttribute("opacity","0");}
  function show(n,at){
    var lines=titleOf(n).split("\n");
    var plants=(n.getAttribute("data-plants")||"").split(",").filter(Boolean);
    var first=lines.length-plants.length;
    clear(tx);clear(ic);
    var w=0;
    for(var i=0;i<lines.length;i++){
      var x=pad,y=pad+lh*i;
      if(i>=first){
        var p=plants[i-first].split(" ");
        var u=document.createElementNS(NS,"use");
        u.setAttribute("href","#plant-"+p[0]+"-still");
        u.setAttribute("x",x);
        u.setAttribute("y",y+(lh-isz)/2);
        u.setAttribute("width",isz);
        u.setAttribute("height",isz);
        u.setAttribute("color",p[1]);
        ic.appendChild(u);
        x+=isz+4;
      }
      var ts=document.createElementNS(NS,"tspan");
      ts.setAttribute("x",x);
      ts.setAttribute("y",y+lh*0.72);
      if(i===0)ts.setAttribute("font-weight","bold");
      ts.textContent=lines[i];
      tx.appendChild(ts);
      w=Math.max(w,x+ts.getComputedTextLength());
    }
    w+=pad;
    var bh=lines.length*lh+pad*2;
    bx.setAttribute("width",w.toFixed(1));
    bx.setAttribute("height",bh.toFixed(1));
    var x0=at.x-w/2,y0=at.y-bh-10;
    if(x0<4)x0=4;
    if(x0+w>vw-4)x0=vw-4-w;
    if(y0<4)y0=at.y+14;
    if(y0+bh>vh-4)y0=vh-4-bh;
    g.setAttribute("transform","translate("+x0.toFixed(1)+","+y0.toFixed(1)+")");
    g.setAttribute("opacity","1");
  }
  function onPointer(e){
    var n=findTooltip(e.target);
    var a=n?pt(e):null;
    if(a)show(n,a);else hide();
  }
  svg.addEventListener("pointerdown",function(e){
    if(e.pointerType!=="mouse")onPointer(e);
  });
  svg.addEventListener("pointermove",function(e){
    if(e.pointerType==="mouse")onPointer(e);
  });
  svg.addEventListener("pointerleave",function(e){
    if(e.pointerType!=="mouse")return;
    hide();
  });
})();
